+
+function joinInlineText(children: MarkdownInline[]): string {
+	return children
+		.map((child) => {
+			switch (child.type) {
+				case "text":
+				case "code":
+				case "htmlInline":
+					return child.value;
+				case "emphasis":
+				case "strong":
+				case "link":
+				case "xref":
+					return joinInlineText(child.children);
+				case "image":
+					return joinInlineText(child.alt);
+				case "hardBreak":
+				case "softBreak":
+					return " ";
+				case "footnoteReference":
+					return child.label ?? child.identifier;
+				case "citation":
+					return child.label ?? child.identifier;
+				default:
+					return "";
+			}
+		})
+		.join("")
+		.replace(/\s+/gu, " ")
+		.trim();
+}
